import {mkdirSync,readFileSync,writeFileSync,symlinkSync,readdirSync,unlinkSync,lstatSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-uat-measure-'),work=storage.dir;
const paths=['scripts/run-uat-verification.ts','scripts/run-uat-verification.test.ts'];
const counters=join(work,'counters');
mkdirSync(join(work,'scripts'));mkdirSync(join(work,'tests','helpers'),{recursive:true});mkdirSync(counters);
const links=['src','node_modules'];
for(const name of links)symlinkSync(join(root,name),join(work,name),process.platform==='win32'?'junction':'dir');
writeFileSync(join(work,'tests/helpers/owned-test-directory.ts'),readFileSync('tests/helpers/owned-test-directory.ts'));
const capture=`\nimport {writeFileSync as saveUatCounters} from 'node:fs';
import {randomUUID as uatCaptureId} from 'node:crypto';
const uatCounterFile=${JSON.stringify(counters)}+'/'+process.pid+'-'+uatCaptureId()+'.json';
(globalThis as any).__captureUat=()=>saveUatCounters(uatCounterFile,JSON.stringify((globalThis as any).__coverage__));
process.on('exit',(globalThis as any).__captureUat);\n`;
for(const path of paths){
 const source=readFileSync(path,'utf8');
 const built=instrumentTypeScriptWithCoverage(source,resolve(path));
 writeFileSync(join(work,path),(path.endsWith('.test.ts')?'':capture)+built.code);
}
writeFileSync(join(work,'capture.ts'),`import {afterAll} from 'bun:test'; afterAll(()=>{(globalThis as any).__captureUat();});`);
writeFileSync(join(work,'bunfig.toml'),'[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts'))+',"./capture.ts"]\n');
console.log('Measuring in owned fixture '+work);
const run=Bun.spawnSync([process.execPath,'test','--timeout','15000','scripts/run-uat-verification.test.ts'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:180000});
const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
writeFileSync('.git/b11-uat-log-measure-run.txt',output);
const batches=readdirSync(counters).map(name=>({name,raw:JSON.parse(readFileSync(join(counters,name),'utf8'))}));
const map=createCoverageMap({});for(const batch of batches)map.merge(batch.raw);
const files=paths.map(path=>{
 const file=map.fileCoverageFor(resolve(path)),data=file.data;
 return {path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:file.toSummary().data,
  uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index],type:data.branchMap[id]?.type}]:[])),
  uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id]),
 };
});
const result={scope:'Diagnostic only: current Istanbul instrumenter has unresolved B05 applicability. Parent and child module counters merged. Generated JavaScript inside test strings is not independently instrumented. No final quality acceptance.',cwd:work,command:[process.execPath,'test','--timeout','15000','scripts/run-uat-verification.test.ts'],exit:run.exitCode,runtime:Bun.version,files,batches,output,harness:readFileSync('.git/b11-uat-log-measure.ts','utf8')};
writeFileSync('.git/b11-uat-log-measure.json',JSON.stringify(result,null,2)+'\n');
storage.assertOwned();
for(const name of links){const link=join(work,name);if(!lstatSync(link).isSymbolicLink())throw Error('Expected probe junction: '+name);unlinkSync(link);}
storage.cleanup();
console.log(JSON.stringify({exit:run.exitCode,counterFiles:batches.length,files,fixtureRemoved:true}));
process.exitCode=run.exitCode;
